// 从自己的公开仓库加载；更新后重新加载脚本，CDN 缓存可能延迟生效。
let disposed = false;
const markDisposed = () => { disposed = true; };
window.addEventListener('pagehide', markDisposed, { once: true });
window.addEventListener('unload', markDisposed, { once: true });
try {
  await import('https://cdn.jsdelivr.net/gh/gqing714-lang/st-attitude-state@main/index.js?reload=' + Date.now());
} catch (error) {
  if (!disposed) {
    console.error('[态度与状态] 在线脚本加载失败：', error);
    alert('态度与状态加载失败。请检查网络后重新启用脚本；也可以使用仓库中的离线版。');
  }
} finally {
  window.removeEventListener('pagehide', markDisposed);
  window.removeEventListener('unload', markDisposed);
}
